rules.logic:
if (element.nextElementSibling && element.nextElementSibling.classList.contains('community-link-moved')) return;
var link = document.querySelector('.need-more-help-option');
if (!link) return;
var clone = link.cloneNode(true);
clone.classList.add('community-link-moved');
clone.style.display = 'flex';
clone.style.alignItems = 'center';
clone.style.gap = '12px';
clone.style.padding = '12px 16px';
clone.style.marginTop = '16px';
clone.style.marginBottom = '16px';
clone.style.borderRadius = '8px';
clone.style.backgroundColor = '#e8f0fe';
clone.style.textDecoration = 'none';
clone.style.color = 'inherit';
clone.style.cursor = 'pointer';
clone.style.transition = 'background-color 0.2s';
var svgContainer = clone.querySelector('.need-more-help-option__svg-container');
if (svgContainer) {
    svgContainer.style.flexShrink = '0';
}
var textWrapper = document.createElement('div');
textWrapper.style.display = 'flex';
textWrapper.style.flexDirection = 'column';
var title = clone.querySelector('.need-more-help-option__title');
var snippet = clone.querySelector('.need-more-help-option__snippet');
if (title) {
    textWrapper.appendChild(title);
    title.style.fontWeight = '600';
    title.style.fontSize = '14px';
}
if (snippet) {
    textWrapper.appendChild(snippet);
    snippet.style.fontSize = '12px';
    snippet.style.color = '#5f6368';
}
clone.innerHTML = '';
clone.appendChild(svgContainer || document.createElement('div'));
clone.appendChild(textWrapper);
element.parentNode.insertBefore(clone, element.nextSibling);
